// ============================================================================
// CẶP PHÔNG CHỮ KÉP HỌC THUẬT: 'Be Vietnam Pro' (UI) + 'STIX Two Text' (Reader)
// ============================================================================
let UI_FONT = { family: 'Be Vietnam Pro', style: 'Regular' };
let ACADEMIC_FONT = { family: 'STIX Two Text', style: 'Regular' };
let FONT_FAMILY = 'Be Vietnam Pro';

const FONT_STYLES = {
  regular: 'Regular',
  medium: 'Medium',
  semibold: 'Semi Bold',
  bold: 'Bold'
};

function sendLog(message, style = '') {
  figma.ui.postMessage({ type: 'PROGRESS_LOG', message, style });
}

async function initFonts() {
  const uiStyles = ['Regular', 'Medium', 'Semi Bold', 'Bold'];
  let uiSuccess = true;
  for (const style of uiStyles) {
    try {
      await figma.loadFontAsync({ family: 'Be Vietnam Pro', style });
    } catch (_err) {
      if (style === 'Semi Bold') {
        try {
          await figma.loadFontAsync({ family: 'Be Vietnam Pro', style: 'SemiBold' });
          FONT_STYLES.semibold = 'SemiBold';
          continue;
        } catch (_err2) {}
      }
      uiSuccess = false;
      break;
    }
  }

  if (uiSuccess) {
    UI_FONT.family = 'Be Vietnam Pro';
    FONT_FAMILY = 'Be Vietnam Pro';
  } else {
    try {
      await figma.loadFontAsync({ family: 'Inter', style: 'Regular' });
      await figma.loadFontAsync({ family: 'Inter', style: 'Medium' });
      await figma.loadFontAsync({ family: 'Inter', style: 'Semi Bold' });
      await figma.loadFontAsync({ family: 'Inter', style: 'Bold' });
      UI_FONT.family = 'Inter';
      FONT_FAMILY = 'Inter';
    } catch (_errInter) {
      try {
        await figma.loadFontAsync({ family: 'Roboto', style: 'Regular' });
        await figma.loadFontAsync({ family: 'Roboto', style: 'Medium' });
        await figma.loadFontAsync({ family: 'Roboto', style: 'Bold' });
        UI_FONT.family = 'Roboto';
        FONT_FAMILY = 'Roboto';
        FONT_STYLES.semibold = 'Bold';
      } catch (_errRoboto) {}
    }
  }

  try {
    await figma.loadFontAsync({ family: 'STIX Two Text', style: 'Regular' });
    await figma.loadFontAsync({ family: 'STIX Two Text', style: 'Medium' });
    await figma.loadFontAsync({ family: 'STIX Two Text', style: 'Bold' });
    ACADEMIC_FONT.family = 'STIX Two Text';
  } catch (_errStix) {
    try {
      await figma.loadFontAsync({ family: 'Times New Roman', style: 'Regular' });
      await figma.loadFontAsync({ family: 'Times New Roman', style: 'Bold' });
      ACADEMIC_FONT.family = 'Times New Roman';
    } catch (_errTimes) {
      ACADEMIC_FONT.family = UI_FONT.family;
    }
  }
}

// ============================================================================
// CÁC HÀM TIỆN ÍCH DỰNG NATIVE FIGMA NODES
// ============================================================================

function solidPaint(color, opacity = 1) {
  return [{ type: 'SOLID', color, opacity }];
}

function createAutoFrame(name, opts = {}) {
  const frame = figma.createFrame();
  frame.name = name;
  const dir = opts.direction || 'VERTICAL';

  if (opts.width && opts.height) {
    frame.resize(opts.width, opts.height);
  } else if (opts.width) {
    frame.resize(opts.width, frame.height || 100);
  } else if (opts.height) {
    frame.resize(frame.width || 100, opts.height);
  }

  frame.layoutMode = dir;
  if (dir === 'HORIZONTAL') {
    frame.primaryAxisSizingMode = opts.width ? 'FIXED' : (opts.primarySizing || 'AUTO');
    frame.counterAxisSizingMode = opts.height ? (opts.counterSizing || 'FIXED') : 'AUTO';
  } else {
    frame.primaryAxisSizingMode = opts.height ? (opts.primarySizing || 'FIXED') : (opts.primarySizing || 'AUTO');
    frame.counterAxisSizingMode = opts.width ? 'FIXED' : (opts.counterSizing || 'AUTO');
  }
  frame.itemSpacing = opts.gap !== undefined ? opts.gap : 12;

  const pad = opts.padding !== undefined ? opts.padding : 0;
  frame.paddingTop = opts.paddingTop !== undefined ? opts.paddingTop : (opts.paddingY !== undefined ? opts.paddingY : pad);
  frame.paddingBottom = opts.paddingBottom !== undefined ? opts.paddingBottom : (opts.paddingY !== undefined ? opts.paddingY : pad);
  frame.paddingLeft = opts.paddingLeft !== undefined ? opts.paddingLeft : (opts.paddingX !== undefined ? opts.paddingX : pad);
  frame.paddingRight = opts.paddingRight !== undefined ? opts.paddingRight : (opts.paddingX !== undefined ? opts.paddingX : pad);

  if (opts.alignPrimary) frame.primaryAxisAlignItems = opts.alignPrimary;
  if (opts.alignCounter) frame.counterAxisAlignItems = opts.alignCounter;

  frame.fills = opts.fill ? solidPaint(opts.fill, opts.fillOpacity !== undefined ? opts.fillOpacity : 1) : [];

  if (opts.stroke) {
    frame.strokes = solidPaint(opts.stroke);
    frame.strokeWeight = opts.strokeWeight || 1;
  }

  if (opts.radius !== undefined) {
    frame.cornerRadius = opts.radius;
  }

  if (opts.shadow) {
    frame.effects = [
      {
        type: 'DROP_SHADOW',
        color: { r: 17 / 255, g: 24 / 255, b: 28 / 255, a: 0.05 },
        offset: { x: 0, y: 4 },
        radius: 12,
        spread: 0,
        visible: true,
        blendMode: 'NORMAL'
      }
    ];
  }

  if (opts.fillWidth) {
    frame.layoutAlign = 'STRETCH';
  }

  return frame;
}

function createText(content, opts = {}) {
  const txt = figma.createText();
  const weightKey = opts.weight || 'regular';
  const styleName = FONT_STYLES[weightKey] || 'Regular';
  txt.fontName = { family: UI_FONT.family, style: styleName };
  txt.characters = String(content);
  txt.fontSize = opts.size || 13;
  txt.fills = solidPaint(opts.color || COLORS.slate12);
  if (opts.lineHeight) {
    txt.lineHeight = { value: opts.lineHeight, unit: 'PIXELS' };
  }
  if (opts.width) {
    txt.resize(opts.width, txt.height);
    txt.textAutoResize = 'HEIGHT';
  }
  return txt;
}

function createAcademicText(content, opts = {}) {
  const txt = figma.createText();
  const weightKey = opts.weight || 'regular';
  const styleName = FONT_STYLES[weightKey] || 'Regular';
  txt.fontName = { family: ACADEMIC_FONT.family, style: styleName };
  txt.characters = String(content);
  txt.fontSize = opts.size || 13.5;
  txt.fills = solidPaint(opts.color || COLORS.slate12);
  if (opts.lineHeight) {
    txt.lineHeight = { value: opts.lineHeight, unit: 'PIXELS' };
  }
  if (opts.width) {
    txt.resize(opts.width, txt.height);
    txt.textAutoResize = 'HEIGHT';
  }
  return txt;
}

function createBadge(label, variant = 'blue', name = 'Badge') {
  const map = {
    blue: { bg: COLORS.blue3, border: COLORS.blue7, text: COLORS.blue11 },
    green: { bg: COLORS.green3, border: COLORS.green7, text: COLORS.green9 },
    amber: { bg: COLORS.amber3, border: COLORS.amber7, text: COLORS.amber11 },
    red: { bg: COLORS.red3, border: COLORS.red7, text: COLORS.red9 },
    slate: { bg: COLORS.slate2, border: COLORS.slate6, text: COLORS.slate11 },
    dark: { bg: COLORS.slate2, border: COLORS.slate6, text: COLORS.slate12 } // 100% Light Mode
  };
  const cfg = map[variant] || map.blue;
  const badge = createAutoFrame(name, {
    direction: 'HORIZONTAL',
    paddingX: 10,
    paddingY: 4,
    gap: 6,
    radius: 999,
    fill: cfg.bg,
    stroke: cfg.border,
    alignCounter: 'CENTER'
  });
  badge.appendChild(createText(label, { size: 11, weight: 'bold', color: cfg.text }));
  return badge;
}

function createButton(label, variant = 'primary', name = 'Btn_' + label) {
  const styles = {
    primary: { bg: COLORS.blue9, border: COLORS.blue10, text: COLORS.white },
    secondary: { bg: COLORS.white, border: COLORS.slate6, text: COLORS.slate12 },
    ghost: { bg: COLORS.slate2, border: COLORS.slate6, text: COLORS.slate11 },
    success: { bg: COLORS.green9, border: COLORS.green9, text: COLORS.white },
    danger: { bg: COLORS.red9, border: COLORS.red9, text: COLORS.white },
    dangerOutline: { bg: COLORS.red3, border: COLORS.red7, text: COLORS.red9 },
    amber: { bg: COLORS.amber3, border: COLORS.amber7, text: COLORS.amber11 }
  };
  const st = styles[variant] || styles.primary;
  const btn = createAutoFrame(name, {
    direction: 'HORIZONTAL',
    paddingX: 16,
    paddingY: 9,
    gap: 8,
    radius: 8,
    fill: st.bg,
    stroke: st.border,
    alignPrimary: 'CENTER',
    alignCounter: 'CENTER'
  });
  btn.appendChild(createText(label, { size: 13, weight: 'bold', color: st.text }));
  return btn;
}

function createInputBox(label, placeholder, valueText = '', width = 360, status = 'default') {
  const wrap = createAutoFrame('Input_Wrap_' + label.replace(/\s+/g, '_'), {
    direction: 'VERTICAL',
    width,
    counterSizing: 'FIXED',
    gap: 6
  });
  wrap.appendChild(createText(label, { size: 12, weight: 'semibold', color: COLORS.slate12 }));
  const strokeColor = status === 'error' ? COLORS.red9 : (status === 'success' ? COLORS.green9 : COLORS.slate6);
  const box = createAutoFrame('Input_Box', {
    direction: 'HORIZONTAL',
    width,
    counterSizing: 'FIXED',
    paddingX: 14,
    paddingY: 10,
    radius: 8,
    fill: COLORS.white,
    stroke: strokeColor,
    alignCounter: 'CENTER'
  });
  box.appendChild(
    createText(valueText || placeholder, {
      size: 13,
      weight: valueText ? 'medium' : 'regular',
      color: valueText ? COLORS.slate12 : COLORS.slate9
    })
  );
  wrap.appendChild(box);
  return wrap;
}

