function createRibbonLogoLockup(size = 38, showWordmark = true) {
  const gap = Math.max(8, Math.round(size * 0.32));
  const fontSize = Math.round(size * 0.61); // size 38 -> 23px giống hệt BrandLogo.jsx

  const brandLockup = createAutoFrame('Brand_Logo_Lockup', {
    direction: 'HORIZONTAL',
    gap,
    alignCounter: 'CENTER'
  });
  brandLockup.name = 'Brand_5Share'; // Alias tương thích ngược

  let iconContainer;
  if (typeof figma.createNodeFromSvg === 'function') {
    iconContainer = figma.createNodeFromSvg(OFFICIAL_BRAND_LOGO_SVG);
    iconContainer.name = 'Logo_Ribbon_Mark';
    iconContainer.resize(size, size);
    iconContainer.fills = [];
  } else {
    iconContainer = figma.createFrame();
    iconContainer.name = 'Logo_Ribbon_Mark';
    iconContainer.resize(size, size);
    iconContainer.fills = [];
  }
  brandLockup.appendChild(iconContainer);

  if (showWordmark) {
    // Wordmark một dòng duy nhất: Số "5" màu xanh Sapphire (#006adc) + chữ "share" màu Slate-12 (#11181c), KHÔNG có dòng phụ
    const wordmarkRow = createAutoFrame('Brand_Wordmark', {
      direction: 'HORIZONTAL',
      gap: 0,
      alignCounter: 'CENTER'
    });
    const digit5 = createText('5', {
      size: fontSize,
      weight: 'bold',
      color: { r: 0 / 255, g: 106 / 255, b: 220 / 255 }
    });
    digit5.name = 'Brand_Wordmark_5';
    const textShare = createText('share', {
      size: fontSize,
      weight: 'bold',
      color: COLORS.slate12
    });
    textShare.name = 'Brand_Wordmark_share';
    wordmarkRow.appendChild(digit5);
    wordmarkRow.appendChild(textShare);
    brandLockup.appendChild(wordmarkRow);
  }

  return brandLockup;
}

// ============================================================================
// HÀM TIỆN ÍCH TẠO NAV LINK VỚI 2PX ACTIVE BAR
// ============================================================================
function createNavLinkItem(label, isActive = false, name = 'Nav_Link') {
  const itemFrame = createAutoFrame(name, {
    direction: 'VERTICAL',
    height: 64,
    primarySizing: 'FIXED',
    counterSizing: 'AUTO',
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER',
    paddingTop: 22,
    paddingBottom: 0,
    gap: 0
  });

  const linkText = createText(label, {
    size: 13.5,
    weight: isActive ? 'semibold' : 'regular',
    color: isActive ? COLORS.blue9 : COLORS.slate11
  });
  itemFrame.appendChild(linkText);

  const indicator = figma.createRectangle();
  indicator.name = 'Active_Indicator_2px';
  indicator.resize(48, 2);
  indicator.cornerRadius = 1;
  indicator.fills = isActive ? solidPaint(COLORS.blue9) : [];
  itemFrame.appendChild(indicator);

  return itemFrame;
}

// ============================================================================
// VECTORIA PRODUCTION TOPBAR 64PX
// Chuẩn 1:1 với Navbar.jsx trên Web Local:
// - Trái: Logo 5share + 5 Tab phẳng (Trang chủ, Kho học liệu, Treo thưởng, Đóng góp, Góp ý)
//   với primarySizing = 'AUTO' để KHÔNG bao giờ bị cắt chữ!
// - Phải: Pill chuyển nhanh vai trò [Khách | Sinh viên | Quản trị] + Chuông thông báo + Avatar tròn 38px
//   (Menu Popover #menuTopAvatar chỉ bung ra tại màn hình SCR_03_Notification_Dropdown để Topbar 64px luôn gọn sạch)
// ============================================================================
function createNavbar(role = 'GUEST', activeTab = 'discovery', showPopoverInline = false) {
  const nav = createAutoFrame('Header_Navbar_' + role, {
    direction: 'HORIZONTAL',
    width: 1440,
    height: 64,
    primarySizing: 'FIXED',
    counterSizing: 'FIXED',
    paddingX: 32,
    paddingY: 0,
    fill: COLORS.white,
    stroke: COLORS.slate6,
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  nav.name = 'Vectoria_Topbar';

  // Left: Layered Ribbon Brand Logo + 5 Full Tabs (AUTO width — zero clipping!)
  const left = createAutoFrame('Nav_Left', {
    direction: 'HORIZONTAL',
    gap: 32,
    alignCounter: 'CENTER'
  });

  const brand = createRibbonLogoLockup();
  left.appendChild(brand);

  // Center: 5 Flat Nav Links with 2px Active Bottom Bar (primarySizing: 'AUTO'!)
  const navLinks = createAutoFrame('Nav_Menu_Links', {
    direction: 'HORIZONTAL',
    gap: 24,
    height: 64,
    primarySizing: 'AUTO',
    counterSizing: 'FIXED',
    alignCounter: 'CENTER'
  });

  const linkLanding = createNavLinkItem('Trang chủ', activeTab === 'landing', 'Nav_Link_Landing');
  const linkDiscovery = createNavLinkItem('Kho học liệu', activeTab === 'discovery', 'Nav_Link_Discovery');
  const linkBounty = createNavLinkItem('Treo thưởng', activeTab === 'bounty', 'Nav_Link_Bounty');
  const linkUpload = createNavLinkItem('Đóng góp', activeTab === 'upload', 'Nav_Link_Upload');
  const linkFeedback = createNavLinkItem('Góp ý', activeTab === 'feedback', 'Nav_Link_Feedback');

  navLinks.appendChild(linkLanding);
  navLinks.appendChild(linkDiscovery);
  navLinks.appendChild(linkBounty);
  navLinks.appendChild(linkUpload);
  navLinks.appendChild(linkFeedback);
  left.appendChild(navLinks);
  nav.appendChild(left);

  // Right Actions: Compact Role Switcher Pill + Notification Bell + Circular 38px Avatar (#btnTopAvatar)
  const right = createAutoFrame('Nav_Right_Actions', {
    direction: 'HORIZONTAL',
    gap: 12,
    alignCounter: 'CENTER'
  });

  // Khối Switcher Pill gọn trên Topbar để bấm chuyển Khách / Sinh viên / Quản trị tức thì
  const personaPill = createAutoFrame('Navbar_Persona_Switcher_Pill', {
    direction: 'HORIZONTAL',
    padding: 3,
    gap: 4,
    radius: 999,
    fill: COLORS.slate2,
    stroke: COLORS.slate6,
    alignCounter: 'CENTER'
  });
  const personaGuest = createBadge('Khách', role === 'GUEST' ? 'blue' : 'slate', 'Persona_Opt_GUEST');
  const personaStudent = createBadge('Sinh viên', role === 'STUDENT' ? 'blue' : 'slate', 'Persona_Opt_STUDENT');
  const personaAdmin = createBadge('Quản trị', role === 'ADMIN' ? 'blue' : 'slate', 'Persona_Opt_ADMIN');
  personaPill.appendChild(personaGuest);
  personaPill.appendChild(personaStudent);
  personaPill.appendChild(personaAdmin);
  right.appendChild(personaPill);

  // Nút chuông thông báo
  let btnBell = null;
  if (role !== 'GUEST') {
    btnBell = createAutoFrame('Btn_Notification_Bell', {
      direction: 'HORIZONTAL',
      width: 36,
      height: 36,
      radius: 18,
      fill: COLORS.slate2,
      stroke: COLORS.slate6,
      alignPrimary: 'CENTER',
      alignCounter: 'CENTER'
    });
    btnBell.appendChild(createText('🔔', { size: 13 }));
    const unreadBadge = figma.createRectangle();
    unreadBadge.name = 'Badge_Unread_Count';
    unreadBadge.resize(8, 8);
    unreadBadge.cornerRadius = 4;
    unreadBadge.fills = solidPaint(COLORS.red9);
    btnBell.appendChild(unreadBadge);
    right.appendChild(btnBell);
  }

  // Nút Avatar tròn 38px (#btnTopAvatar)
  const btnTopAvatar = createAutoFrame('Btn_Top_Avatar', {
    direction: 'HORIZONTAL',
    width: 38,
    height: 38,
    radius: 19,
    stroke: COLORS.slate6,
    alignPrimary: 'CENTER',
    alignCounter: 'CENTER'
  });
  btnTopAvatar.name = '#btnTopAvatar';

  if (role === 'GUEST') {
    btnTopAvatar.fills = solidPaint(COLORS.slate2);
    btnTopAvatar.appendChild(createText('👤', { size: 13 }));
  } else if (role === 'STUDENT') {
    btnTopAvatar.fills = solidPaint({ r: 62 / 255, g: 99 / 255, b: 221 / 255 }); // Indigo
    btnTopAvatar.appendChild(createText('TV', { size: 12.5, weight: 'bold', color: COLORS.white }));
  } else if (role === 'ADMIN') {
    btnTopAvatar.fills = solidPaint(COLORS.green9);
    btnTopAvatar.appendChild(createText('ĐK', { size: 12.5, weight: 'bold', color: COLORS.white }));
  }
  right.appendChild(btnTopAvatar);

  // Popover Menu (#menuTopAvatar) — chỉ gắn vào cây hiển thị khi showPopoverInline = true (hoặc lấy ra gắn vào SCR_03)
  const menuPopover = createAutoFrame('Menu_Top_Avatar', {
    direction: 'VERTICAL',
    width: 260,
    counterSizing: 'FIXED',
    radius: 12,
    padding: 12,
    gap: 8,
    fill: COLORS.white,
    stroke: COLORS.slate6,
    shadow: true
  });
  menuPopover.name = '#menuTopAvatar';

  const menuItemProfile = createButton('👤 Hồ sơ cá nhân (/profile)', 'ghost', 'Menu_Item_Profile');
  menuItemProfile.layoutAlign = 'STRETCH';
  const menuItemMyDocs = createButton('📁 Kho tài liệu của tôi', 'ghost', 'Menu_Item_MyDocs');
  menuItemMyDocs.layoutAlign = 'STRETCH';
  const menuItemBookmarks = createButton('🔖 Tủ tài liệu đã lưu', 'ghost', 'Menu_Item_Bookmarks');
  menuItemBookmarks.layoutAlign = 'STRETCH';
  const menuItemLogout = createButton('🚪 Đăng xuất tài khoản', 'dangerOutline', 'Menu_Item_Logout');
  menuItemLogout.layoutAlign = 'STRETCH';

  menuPopover.appendChild(menuItemProfile);
  menuPopover.appendChild(menuItemMyDocs);
  menuPopover.appendChild(menuItemBookmarks);
  menuPopover.appendChild(menuItemLogout);

  if (showPopoverInline) {
    right.appendChild(menuPopover);
  }

  // Các nút điều hướng tương thích ngược cho bộ nối dây Prototype
  const btnLogin = role === 'GUEST' ? btnTopAvatar : createButton('Đăng nhập', 'secondary', 'Nav_Btn_Login');
  const btnRegister = createButton('Đăng ký', 'primary', 'Nav_Btn_Register');
  const btnExplore = linkDiscovery;
  const btnUpload = linkUpload;
  const btnMyDocs = menuItemMyDocs;
  const btnBookmarks = menuItemBookmarks;
  const btnModeration = createButton('Hàng đợi kiểm duyệt', 'primary', 'Nav_Btn_Moderation');
  const btnCourses = createButton('Quản lý danh mục', 'ghost', 'Nav_Btn_Courses');
  const btnDashboard = createButton('Tổng quan hệ thống', 'ghost', 'Nav_Btn_Dashboard');
  const btnRoleSwitch = personaAdmin;

  nav.appendChild(right);

  return {
    node: nav,
    brand,
    btnExplore,
    btnUpload,
    btnMyDocs,
    btnBookmarks,
    btnModeration,
    btnCourses,
    btnDashboard,
    btnLogin,
    btnRegister,
    btnBell: btnBell || btnTopAvatar,
    btnRoleSwitch,
    personaGuest,
    personaStudent,
    personaAdmin,
    btnTopAvatar,
    menuPopover,
    menuItemProfile,
    menuItemMyDocs,
    menuItemBookmarks,
    menuItemLogout,
    linkLanding,
    linkDiscovery,
    linkBounty,
    linkUpload,
    linkFeedback,
    linkExplore: linkFeedback
  };
}

function createSidebarItemRow(label, countText = '', isActive = false, width = 204, name = 'Sidebar_Item') {
  const row = createAutoFrame(name, {
    direction: 'HORIZONTAL',
    width,
    primarySizing: 'FIXED',
    paddingX: 10,
    paddingY: 8,
    radius: 8,
    fill: isActive ? COLORS.blue3 : COLORS.white,
    stroke: isActive ? COLORS.blue7 : undefined,
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  row.appendChild(
    createText(label, {
      size: 12,
      weight: isActive ? 'bold' : 'medium',
      color: isActive ? COLORS.blue11 : COLORS.slate12
    })
  );
  if (countText !== '') {
    const pill = createAutoFrame('Count_Pill', {
      direction: 'HORIZONTAL',
      paddingX: 7,
      paddingY: 2,
      radius: 999,
      fill: isActive ? COLORS.white : COLORS.slate2,
      stroke: isActive ? COLORS.blue7 : COLORS.slate6,
      alignCounter: 'CENTER'
    });
    pill.appendChild(
      createText(String(countText), {
        size: 10,
        weight: 'bold',
        color: isActive ? COLORS.blue11 : COLORS.slate11
      })
    );
    row.appendChild(pill);
  }
  return row;
}

function createSelectDropdownBox(label, valueText, width = 258) {
  const wrap = createAutoFrame('Select_Wrap_' + label.slice(0, 10).replace(/\s+/g, '_'), {
    direction: 'VERTICAL',
    width,
    counterSizing: 'FIXED',
    gap: 4
  });
  wrap.appendChild(createText(label, { size: 10.5, weight: 'bold', color: COLORS.slate11 }));
  const box = createAutoFrame('Select_Control_Box', {
    direction: 'HORIZONTAL',
    width,
    primarySizing: 'FIXED',
    paddingX: 12,
    paddingY: 8,
    radius: 8,
    fill: COLORS.white,
    stroke: COLORS.slate7,
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  box.appendChild(createText(valueText, { size: 12, weight: 'semibold', color: COLORS.slate12 }));
  box.appendChild(createText('▾', { size: 12, weight: 'bold', color: COLORS.slate11 }));
  wrap.appendChild(box);
  return wrap;
}

// ============================================================================
// HÀM DỰNG ADMIN SIDEBAR 240PX (100% LIGHT MODE - FULL-WIDTH SIDEBAR ITEMS)
// ============================================================================
function createAdminDarkSidebar(activeSection = 'moderation', height = 878, suffix = '') {
  const sidebarName = suffix ? `Admin_Dark_Sidebar_${suffix}` : 'Admin_Dark_Sidebar';
  const sidebar = createAutoFrame(sidebarName, {
    direction: 'VERTICAL',
    width: 240,
    height,
    primarySizing: 'FIXED',
    counterSizing: 'FIXED',
    padding: 18,
    gap: 8,
    fill: COLORS.white,
    stroke: COLORS.slate6
  });

  sidebar.appendChild(createText('5SHARE ADMIN WORKSPACE', { size: 10, weight: 'bold', color: COLORS.blue9 }));
  sidebar.appendChild(createText('Quản trị Học liệu Khoa CNTT', { size: 13.5, weight: 'bold', color: COLORS.slate12 }));

  const navDashboard = createSidebarItemRow('📊 Tổng quan hệ thống', '', activeSection === 'dashboard', 204, 'Admin_Nav_Item_dashboard');
  sidebar.appendChild(navDashboard);

  const navModeration = createAutoFrame('Admin_Nav_Item_moderation', {
    direction: 'HORIZONTAL',
    width: 204,
    primarySizing: 'FIXED',
    paddingX: 10,
    paddingY: 8,
    radius: 8,
    fill: activeSection === 'moderation' ? COLORS.blue3 : COLORS.white,
    stroke: activeSection === 'moderation' ? COLORS.blue7 : undefined,
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  navModeration.appendChild(
    createText('🛡 Kiểm duyệt học liệu', {
      size: 12,
      weight: activeSection === 'moderation' ? 'bold' : 'medium',
      color: activeSection === 'moderation' ? COLORS.blue11 : COLORS.slate12
    })
  );
  const redBadge = createBadge('3', 'red', 'Admin_Pending_Red_Badge');
  navModeration.appendChild(redBadge);
  sidebar.appendChild(navModeration);

  const navCourses = createSidebarItemRow('📚 Quản lý môn học CTĐT', '47', activeSection === 'courses', 204, 'Admin_Nav_Item_courses');
  sidebar.appendChild(navCourses);

  const navUsers = createSidebarItemRow('👥 Quản lý người dùng', '148', activeSection === 'users', 204, 'Admin_Nav_Item_users');
  sidebar.appendChild(navUsers);

  const navBackExplore = createButton('← Quay về Kho học liệu', 'ghost', 'Admin_Nav_Item_explore');
  navBackExplore.layoutAlign = 'STRETCH';
  sidebar.appendChild(navBackExplore);

  return {
    node: sidebar,
    navDashboard,
    navModeration,
    navCourses,
    navUsers,
    navBackExplore
  };
}

// ============================================================================
// HÀM DỰNG BẢNG DESIGN SYSTEM & COMPONENT GỐC
// ============================================================================
function buildDesignSystemFrame(page, x, y) {
  const ds = createAutoFrame('00_Design_System_Components', {
    direction: 'VERTICAL',
    width: 1440,
    counterSizing: 'FIXED',
    padding: 32,
    gap: 20,
    fill: COLORS.white,
    stroke: COLORS.slate6,
    radius: 16,
    shadow: true
  });
  ds.x = x;
  ds.y = y;

  ds.appendChild(
    createText('HỆ THỐNG DESIGN SYSTEM & COMPONENT GỐC - DỰ ÁN 5SHARE (HCMUE)', {
      size: 20,
      weight: 'bold',
      color: COLORS.slate12
    })
  );
  ds.appendChild(
    createText(
      'Toàn bộ 19 màn hình dưới đây được dựng 100% bằng Native Figma Nodes (Auto Layout + Vector + Text), chuẩn Radix Light Mode và nối dây Prototype tự động.',
      { size: 13, color: COLORS.slate11 }
    )
  );

  // Hàng 1: Swatches màu sắc Radix Light Mode
  const colorRow = createAutoFrame('Radix_Color_Tokens', {
    direction: 'HORIZONTAL',
    gap: 14
  });
  const swatches = [
    { name: 'Brand Blue-9 (#0090FF)', color: COLORS.blue9 },
    { name: 'Blue-11 (#0D74CE)', color: COLORS.blue11 },
    { name: 'Text Primary Slate-12 (#11181C)', color: COLORS.slate12 },
    { name: 'Text Muted Slate-11 (#687076)', color: COLORS.slate11 },
    { name: 'Approved Green-9 (#30A46C)', color: COLORS.green9 },
    { name: 'Pending Amber-9 (#FFB224)', color: COLORS.amber9 },
    { name: 'Rejected Red-9 (#E5484D)', color: COLORS.red9 }
  ];
  for (const s of swatches) {
    const item = createAutoFrame('Token_' + s.name, {
      direction: 'HORIZONTAL',
      padding: 10,
      gap: 10,
      radius: 8,
      fill: COLORS.slate2,
      stroke: COLORS.slate6,
      alignCounter: 'CENTER'
    });
    const rect = figma.createRectangle();
    rect.name = 'Swatch';
    rect.resize(24, 24);
    rect.cornerRadius = 6;
    rect.fills = solidPaint(s.color);
    item.appendChild(rect);
    item.appendChild(createText(s.name, { size: 12, weight: 'semibold', color: COLORS.slate12 }));
    colorRow.appendChild(item);
  }
  ds.appendChild(colorRow);

  // Hàng 2: Native Components Row
  const compRow = createAutoFrame('Native_Components_Row', {
    direction: 'HORIZONTAL',
    gap: 16,
    alignCounter: 'CENTER'
  });
  compRow.appendChild(createBadge('✓ APPROVED (+20đ)', 'green', 'Comp_Status_APPROVED'));
  compRow.appendChild(createBadge('⏳ PENDING (8 tiêu chí)', 'amber', 'Comp_Status_PENDING'));
  compRow.appendChild(createBadge('✕ REJECTED', 'red', 'Comp_Status_REJECTED'));
  compRow.appendChild(createBadge('COMP1044 • PPDH Tin học', 'blue', 'Comp_Course_Tag'));
  compRow.appendChild(createButton('Nút Chính (Primary)', 'primary', 'Comp_Btn_Primary'));
  compRow.appendChild(createButton('Nút Phụ (Secondary)', 'secondary', 'Comp_Btn_Secondary'));
  ds.appendChild(compRow);

  page.appendChild(ds);
  return ds;
}

// ============================================================================
// HÀM DỰNG THẺ HỌC LIỆU EDITORIAL FOLIO (.vec-folio-card - PDF / DOCX / PPTX)
// Đồng bộ 100% với client/src/components/home/DocumentCard.jsx:
// - Stage trên: Pill Mã HP · HK + Nút Bookmark + Tờ giấy A4 / Slide thu nhỏ nổi 3D
// - Thân dưới tối giản 3 phần: Tên môn + Loại học liệu, Tiêu đề Serif, Footer Rating · Lượt tải | Định dạng · Số trang
// ============================================================================
function createDocumentCardNode(doc) {
  const card = createAutoFrame('DocCard_' + doc.code, {
    direction: 'VERTICAL',
    width: 340,
    counterSizing: 'FIXED',
    padding: 0,
    gap: 0,
    radius: 14,
    fill: COLORS.white,
    stroke: COLORS.slate6,
    shadow: true
  });
  card.primaryAxisSizingMode = 'AUTO';
  card.counterAxisSizingMode = 'FIXED';

  const format = (doc.format || 'pdf').toLowerCase();
  let badgeColor = 'red';
  let formatShort = 'PDF';
  let unitLabel = 'trang';

  if (format === 'docx') {
    badgeColor = 'blue';
    formatShort = 'DOCX';
    unitLabel = 'trang';
  } else if (format === 'pptx') {
    badgeColor = 'amber';
    formatShort = 'PPTX';
    unitLabel = 'slides';
  }

  const semShort = String(doc.semester || 'HK5').replace('Học kỳ ', 'HK');

  // 1. Top Stage (.vec-folio-stage / Doc_Mini_A4_Sheet_Stage)
  const sheetStage = createAutoFrame('Doc_Mini_A4_Sheet_Stage', {
    direction: 'VERTICAL',
    width: 340,
    counterSizing: 'FIXED',
    paddingX: 16,
    paddingY: 14,
    gap: 10,
    fill: COLORS.slate2,
    alignCounter: 'CENTER'
  });

  const stageHeader = createAutoFrame('Mini_Stage_Header', {
    direction: 'HORIZONTAL',
    width: 308,
    primarySizing: 'FIXED',
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  stageHeader.appendChild(createBadge(`${doc.courseCode} · ${semShort}`, 'slate'));
  stageHeader.appendChild(createBadge('🔖', 'slate', 'Btn_Folio_Bookmark_' + doc.code));
  sheetStage.appendChild(stageHeader);

  // Miniature A4 Paper Sheet or Slide Deck
  const miniSheet = createAutoFrame('Mini_A4_Paper_Sheet', {
    direction: 'VERTICAL',
    width: format === 'pptx' ? 248 : 196,
    counterSizing: 'FIXED',
    padding: 12,
    gap: 6,
    radius: 6,
    fill: COLORS.white,
    stroke: COLORS.slate6,
    shadow: true
  });

  const sheetTopRow = createAutoFrame('Mini_Sheet_Top_Row', {
    direction: 'HORIZONTAL',
    width: format === 'pptx' ? 224 : 172,
    primarySizing: 'FIXED',
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  sheetTopRow.appendChild(createBadge(formatShort, badgeColor));
  sheetTopRow.appendChild(createText(`${doc.pages} ${ format === 'pptx' ? 'sl.' : 'tr.' }`, { size: 9.5, weight: 'semibold', color: COLORS.slate11 }));
  miniSheet.appendChild(sheetTopRow);

  const line1 = figma.createRectangle();
  line1.name = 'Paper_Line_Title';
  line1.resize(format === 'pptx' ? 180 : 148, 5);
  line1.cornerRadius = 2;
  line1.fills = solidPaint(COLORS.slate7);
  miniSheet.appendChild(line1);

  const line2 = figma.createRectangle();
  line2.name = 'Paper_Line_Sub';
  line2.resize(format === 'pptx' ? 140 : 120, 4);
  line2.cornerRadius = 2;
  line2.fills = solidPaint(COLORS.slate6);
  miniSheet.appendChild(line2);

  const line3 = figma.createRectangle();
  line3.name = 'Paper_Line_Body';
  line3.resize(format === 'pptx' ? 160 : 96, 4);
  line3.cornerRadius = 2;
  line3.fills = solidPaint(COLORS.slate3);
  miniSheet.appendChild(line3);

  sheetStage.appendChild(miniSheet);
  card.appendChild(sheetStage);

  // 2. Bottom Body (.vec-folio-body / Doc_Card_Body) — 3 phần tinh gọn
  const cardBody = createAutoFrame('Doc_Card_Body', {
    direction: 'VERTICAL',
    width: 340,
    counterSizing: 'FIXED',
    padding: 16,
    gap: 8,
    fill: COLORS.white
  });

  // Phần 1: Tên học phần + Pill loại tài liệu
  const eyebrowRow = createAutoFrame('Folio_Eyebrow_Row', {
    direction: 'HORIZONTAL',
    width: 308,
    primarySizing: 'FIXED',
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  eyebrowRow.appendChild(
    createText(doc.courseName, {
      size: 11,
      weight: 'semibold',
      color: COLORS.slate11
    })
  );
  eyebrowRow.appendChild(createBadge(doc.docType || 'Học liệu', 'blue'));
  cardBody.appendChild(eyebrowRow);

  // Phần 2: Tiêu đề Học thuật (STIX Two Text Serif)
  cardBody.appendChild(
    createAcademicText(doc.title, {
      size: 14,
      weight: 'bold',
      color: COLORS.slate12,
      width: 308,
      lineHeight: 20
    })
  );

  // Phần 3: Footer gọn (★ Rating · Lượt tải | Format · Số trang →)
  const metaRow = createAutoFrame('Card_Essential_Meta', {
    direction: 'HORIZONTAL',
    width: 308,
    primarySizing: 'FIXED',
    paddingTop: 6,
    alignPrimary: 'SPACE_BETWEEN',
    alignCounter: 'CENTER'
  });
  const ratingShort = String(doc.rating || '4.9').split(' ')[0];
  metaRow.appendChild(
    createText(`★ ${ratingShort} · ${doc.downloads} lượt tải`, {
      size: 11.5,
      weight: 'semibold',
      color: COLORS.slate11
    })
  );

  const btnPreview = createButton(`${formatShort} · ${doc.pages} ${unitLabel} →`, 'ghost', 'Btn_Open_' + doc.code);
  metaRow.appendChild(btnPreview);
  cardBody.appendChild(metaRow);

  card.appendChild(cardBody);

  return { card, btnPreview };
}

