// ============================================================================
// HÀM KẾT NỐI DÂY NỐI PROTOTYPE (setReactionsAsync)
// ============================================================================
async function connectWire(sourceNode, targetScreen, navType = 'NAVIGATE', useSmartAnimate = false) {
  if (!sourceNode || !targetScreen) return false;

  const reaction = {
    trigger: { type: 'ON_CLICK' },
    actions: [
      {
        type: 'NODE',
        destinationId: targetScreen.id,
        navigation: navType,
        transition: useSmartAnimate
          ? { type: 'SMART_ANIMATE', easing: { type: 'EASE_IN_AND_OUT' }, duration: 0.28 }
          : { type: 'DISSOLVE', easing: { type: 'EASE_OUT' }, duration: 0.2 }
      }
    ]
  };

  try {
    if (typeof sourceNode.setReactionsAsync === 'function') {
      await sourceNode.setReactionsAsync([reaction]);
      return true;
    }
  } catch (_e) {
    try {
      const basicReaction = {
        trigger: { type: 'ON_CLICK' },
        actions: [{ type: 'NODE', destinationId: targetScreen.id, navigation: 'NAVIGATE' }]
      };
      await sourceNode.setReactionsAsync([basicReaction]);
      return true;
    } catch (_e2) {
      return false;
    }
  }
  return false;
}

