const B64_LOOKUP = (() => {
  const chars = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  const table = new Uint8Array(256);
  for (let i = 0; i < chars.length; i++) table[chars.charCodeAt(i)] = i;
  return table;
})();

function base64ToUint8Array(b64) {
  const len = b64.length;
  let pad = 0;
  if (len > 0 && b64[len - 1] === '=') pad++;
  if (len > 1 && b64[len - 2] === '=') pad++;
  const outLen = ((len * 3) >> 2) - pad;
  const bytes = new Uint8Array(outLen);
  let p = 0;
  for (let i = 0; i < len; i += 4) {
    const c0 = B64_LOOKUP[b64.charCodeAt(i)];
    const c1 = B64_LOOKUP[b64.charCodeAt(i + 1)];
    const c2 = B64_LOOKUP[b64.charCodeAt(i + 2)];
    const c3 = B64_LOOKUP[b64.charCodeAt(i + 3)];
    const triplet = (c0 << 18) | (c1 << 12) | (c2 << 6) | c3;
    if (p < outLen) bytes[p++] = (triplet >> 16) & 0xff;
    if (p < outLen) bytes[p++] = (triplet >> 8) & 0xff;
    if (p < outLen) bytes[p++] = triplet & 0xff;
  }
  return bytes;
}

