function prefixCollidingLegacyNames(node) {
  if (node && node.name && HOTSPOT_NAME_SET.has(node.name)) {
    node.name = 'Legacy_' + node.name;
  }
  if (node && Array.isArray(node.children)) {
    for (const c of node.children) prefixCollidingLegacyNames(c);
  }
}

async function applyWebExactVisualsAndHotspots(screens, includeWires) {
  const COL_W_EXACT = 1620;
  // 48px Browser Safe Top Bar prevents Figma Prototype's 48px black header bar from covering the 5share Topbar!
  const FIGMA_UI_SAFE_TOP = 48;
  let hotspotWires = 0;

  for (const [scrKey, scrNode] of Object.entries(screens)) {
    if (!scrKey.startsWith('SCR_')) continue;
    const visual = SCREEN_VISUAL_TILES[scrKey];
    if (!visual || !scrNode) continue;

    prefixCollidingLegacyNames(scrNode);
    for (const legacyChild of scrNode.children || []) {
      legacyChild.visible = false;
    }

    const pos = SCREEN_GRID_POSITIONS[scrKey];
    if (pos) {
      scrNode.x = pos.col * COL_W_EXACT;
      scrNode.y = pos.y;
    }

    const totalHeight = visual.height + FIGMA_UI_SAFE_TOP;
    scrNode.resize(visual.width, totalHeight);
    scrNode.primaryAxisSizingMode = 'FIXED';
    scrNode.counterAxisSizingMode = 'FIXED';
    scrNode.clipsContent = true;

    // 1. Create 48px Browser Safe Top Bar at y = 0..48 so Figma's black Prototype bar never covers the 5share Topbar
    const browserBar = figma.createFrame();
    browserBar.name = 'Browser_Safe_Header_48px';
    browserBar.resize(visual.width, FIGMA_UI_SAFE_TOP);
    browserBar.fills = [{ type: 'SOLID', color: { r: 0.945, g: 0.961, b: 0.976 } }];
    scrNode.appendChild(browserBar);
    browserBar.layoutPositioning = 'ABSOLUTE';
    browserBar.x = 0;
    browserBar.y = 0;

    const dotColors = [
      { r: 1.0, g: 0.373, b: 0.341 },
      { r: 0.996, g: 0.737, b: 0.180 },
      { r: 0.157, g: 0.784, b: 0.251 }
    ];
    for (let d = 0; d < 3; d++) {
      const dot = figma.createRectangle();
      dot.name = 'Window_Dot_' + (d + 1);
      dot.resize(12, 12);
      dot.cornerRadius = 6;
      dot.x = 20 + d * 20;
      dot.y = 18;
      dot.fills = [{ type: 'SOLID', color: dotColors[d] }];
      browserBar.appendChild(dot);
    }

    const urlBar = figma.createFrame();
    urlBar.name = 'Browser_Address_Bar';
    urlBar.resize(520, 28);
    urlBar.cornerRadius = 6;
    urlBar.x = Math.round((visual.width - 520) / 2);
    urlBar.y = 10;
    urlBar.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 } }];
    browserBar.appendChild(urlBar);

    const urlText = createText('🔒 https://5share.io.vn — Hệ thống Quản lý & Chia sẻ Học liệu SPTH (HCMUE)', {
      size: 11.5,
      weight: 'medium',
      color: COLORS.slate11
    });
    urlText.x = 24;
    urlText.y = 6;
    urlBar.appendChild(urlText);

    // 2. Render Web_Exact_Viewport_Render starting at y = FIGMA_UI_SAFE_TOP (48px)
    const renderFrame = figma.createFrame();
    renderFrame.name = 'Web_Exact_Viewport_Render';
    renderFrame.resize(visual.width, visual.height);
    renderFrame.fills = [];
    renderFrame.clipsContent = true;
    scrNode.appendChild(renderFrame);
    renderFrame.layoutPositioning = 'ABSOLUTE';
    renderFrame.x = 0;
    renderFrame.y = FIGMA_UI_SAFE_TOP;

    for (let idx = 0; idx < visual.tiles.length; idx++) {
      const t = visual.tiles[idx];
      const imgBytes = base64ToUint8Array(t.b64);
      const imgObj = figma.createImage(imgBytes);
      const sliceRect = figma.createRectangle();
      sliceRect.name = 'Viewport_Tile_' + (idx + 1);
      sliceRect.resize(visual.width, t.h);
      sliceRect.x = 0;
      sliceRect.y = t.y;
      sliceRect.fills = [{ type: 'IMAGE', scaleMode: 'FILL', imageHash: imgObj.hash }];
      renderFrame.appendChild(sliceRect);
    }

    const isGuestScreen = ['SCR_01', 'SCR_02', 'SCR_06'].includes(scrKey);
    const isAdminScreen = ['SCR_10', 'SCR_11', 'SCR_13', 'SCR_17'].includes(scrKey);

    const commonHotspots = [
      { name: 'Brand_5share', x: 22, y: 11, w: 120, h: 32, target: 'SCR_05' },
      { name: 'Nav_Link_Landing', x: 162, y: 12, w: 78, h: 30, target: 'SCR_00' },
      { name: 'Nav_Link_Discovery', x: 256, y: 12, w: 114, h: 30, target: 'SCR_05' },
      { name: 'Nav_Link_Bounty', x: 388, y: 12, w: 110, h: 30, target: 'SCR_16' },
      { name: 'Nav_Link_Upload', x: 514, y: 12, w: 98, h: 30, target: 'SCR_08' },
      { name: 'Nav_Link_Feedback', x: 628, y: 12, w: 72, h: 30, target: 'SCR_18' },
      { name: 'Btn_Topbar_Bell', x: 1335, y: 9, w: 36, h: 36, target: 'SCR_03' },
      { name: 'Btn_Topbar_Avatar', x: 1381, y: 9, w: 38, h: 36, target: isGuestScreen ? 'SCR_01' : 'SCR_15' },
      { name: 'Btn_Open_Feedback_Modal', x: 1276, y: visual.height - 52, w: 148, h: 38, target: 'SCR_18' }
    ];

    if (isAdminScreen) {
      commonHotspots.push(
        { name: 'Admin_Nav_Item_dashboard', x: 12, y: 152, w: 216, h: 36, target: 'SCR_13' },
        { name: 'Admin_Nav_Item_moderation', x: 12, y: 197, w: 216, h: 36, target: 'SCR_10' },
        { name: 'Admin_Nav_Item_courses', x: 12, y: 242, w: 216, h: 36, target: 'SCR_11' },
        { name: 'Admin_Nav_Item_explore', x: 12, y: 286, w: 216, h: 36, target: 'SCR_17' }
      );
    }

    const allHotspots = [...commonHotspots, ...(SCREEN_SPECIFIC_HOTSPOTS[scrKey] || [])];
    for (const h of allHotspots) {
      const dstScreen = screens[h.target];
      if (!dstScreen || dstScreen === scrNode) continue;
      const hs = figma.createFrame();
      hs.name = h.name;
      hs.resize(h.w, h.h);
      hs.fills = [{ type: 'SOLID', color: { r: 1, g: 1, b: 1 }, opacity: 0.001 }];
      scrNode.appendChild(hs);
      hs.layoutPositioning = 'ABSOLUTE';
      hs.x = h.x;
      hs.y = h.y + FIGMA_UI_SAFE_TOP;
      if (includeWires !== false) {
        const ok = await connectWire(hs, dstScreen, 'NAVIGATE', true);
        if (ok) hotspotWires++;
      }
    }
  }

  return hotspotWires;
}
