    const addWire = async (_src, _dst, _type = 'NAVIGATE', _smart = true) => {
      // Legacy underlying nodes are skipped so only exact-coordinate Hotspots on Web_Exact_Viewport_Render have Prototype wires
      return;
    };

    // 0. Nối dây Persona Switcher & 5 Tab Topbar trên toàn bộ 19 màn hình
