        await addWire(refObj.nav.personaStudent, screens.SCR_07, 'NAVIGATE', false);
        await addWire(refObj.nav.personaAdmin, screens.SCR_10, 'NAVIGATE', false);
        await addWire(refObj.nav.linkLanding, screens.SCR_00, 'NAVIGATE', true);
